export async function loadFarmerPrivate(ctx: Ctx, f: typeof farmers.$inferSelect): Promise<FarmerPrivate> {
  const ps = await ctx.db.select().from(plots).where(eq(plots.farmerId, f.id));
  return {
    farmerToken: f.token, village: f.village as VillageCode, gender: f.gender as 'F' | 'M' | 'O', joinedOn: f.joinedOn, erased: f.erased,
    id: f.id, name: f.name, nameLocal: f.nameLocal, phone: f.phone, preferredLang: f.preferredLang as 'bn' | 'hi' | 'en',
    plots: ps.map((p) => ({ plotId: p.plotId, areaHa: p.areaHa, crops: p.crops as Commodity[], polygonHash: p.polygonHash })),
  };
}

export function farmersRoutes(ctx: Ctx): Partial<Record<EndpointId, Handler>> {
  const getFarmer = async (id: string) => {
    const f = (await ctx.db.select().from(farmers).where(eq(farmers.id, id)))[0];
    if (!f) throw notFound('Farmer');
    return f;
  };

  return {
    async registerFarmer(req) {
      const u = user(req);
      const b = parse(registerBody, req.body, 'farmer');
      if ((await ctx.db.select({ id: farmers.id }).from(farmers).where(and(eq(farmers.phone, b.phone), ne(farmers.erased, true))))[0]) throw invalid('A member with this phone number is already registered.');
      const id = randomUUID(), token = farmerToken(ctx.cfg.FARMER_TOKEN_SECRET, id), plotId = newPlotId();
      const polygonHash = hashCanonical(b.plot.geojson), consentHash = hashCanonical(b.consent);
      const joinedOn = istDate(ctx.now());
      return ctx.db.transaction(async (tx) => {
        await tx.insert(farmers).values({ id, token, name: b.name, nameLocal: b.nameLocal, gender: b.gender, phone: b.phone, village: b.village, preferredLang: b.consent.lang, devicePublicKeyHex: b.devicePublicKeyHex ?? '', consent: b.consent, joinedOn });
        await tx.insert(plots).values({ plotId, farmerId: id, areaHa: b.plot.areaHa, crops: b.plot.crops, geojson: b.plot.geojson, polygonHash });
        const { receipt } = await submit(ctx, fabricUserOf(u), 'trace-channel', 'lot-lifecycle', 'RegisterFarmerAndPlot', [token, b.devicePublicKeyHex ?? '', consentHash, plotId, polygonHash], ENDORSE.trace);
        const row = (await tx.select().from(farmers).where(eq(farmers.id, id)))[0]!;
        const ps = await tx.select().from(plots).where(eq(plots.farmerId, id));
        return receipted(receipt, { farmerToken: token, village: b.village, gender: b.gender, joinedOn, erased: false, id, name: row.name, nameLocal: row.nameLocal, phone: row.phone, preferredLang: row.preferredLang as 'bn', plots: ps.map((p) => ({ plotId: p.plotId, areaHa: p.areaHa, crops: p.crops as Commodity[], polygonHash: p.polygonHash })) } satisfies FarmerPrivate);
      });
    },

    async listFarmers(req) {
      const q = req.query as { village?: string; cursor?: string; limit?: string };
      const { limit, offset } = pageParams(q);
      const rows = await ctx.db.select().from(farmers).where(q.village ? eq(farmers.village, q.village) : undefined).orderBy(asc(farmers.joinedOn), asc(farmers.id)).limit(limit + 1).offset(offset);
      const items = await Promise.all(rows.slice(0, limit).map((f) => loadFarmerPrivate(ctx, f)));
      return { items, nextCursor: nextCursor(offset, limit, rows.length) };
    },

    async getMyFarmer(req) { return loadFarmerPrivate(ctx, await getFarmer(user(req).id)); },

    async registerDeviceKey(req) {
      const u = user(req);
      const b = parse(keyBody, req.body, 'device key');
      const f = await getFarmer(u.id);
      if (f.erased) throw new HttpError('ERR_INVALID_STATE', 'This member has erased their data.');
      return ctx.db.transaction(async (tx) => {
        await tx.update(farmers).set({ devicePublicKeyHex: b.publicKeyHex }).where(eq(farmers.id, f.id));
        const { receipt } = await submit(ctx, fabricUserOf(u), 'trace-channel', 'lot-lifecycle', 'RegisterDeviceKey', [f.token, b.publicKeyHex], ENDORSE.trace);
        return receipted(receipt, { farmerToken: f.token, devicePublicKeyHex: b.publicKeyHex });
      });
    },

    async erasePersonalData(req) {
      const u = user(req);
      const { id } = req.params as { id: string };
      if (u.role === 'member' && u.id !== id) throw forbidden('A member can erase only their own data.');
      const f = await getFarmer(id);
      if (f.erased) throw new HttpError('ERR_INVALID_STATE', 'This member has already erased their data.');
      return ctx.db.transaction(async (tx) => {
        await tx.update(farmers).set({ name: '', nameLocal: '', phone: '', devicePublicKeyHex: '', consent: null, erased: true }).where(eq(farmers.id, id));
        await tx.update(plots).set({ geojson: null }).where(eq(plots.farmerId, id));
        await tx.update(diaryInputs).set({ product: '', activeIngredient: '', dose: '' }).where(eq(diaryInputs.farmerId, id));
        const { receipt } = await submit(ctx, serviceUser('ceo'), 'trace-channel', 'lot-lifecycle', 'MarkUnverifiable', [f.token], ENDORSE.trace);
        const lots = await ctx.db.execute<{ n: number }>(ctxSqlCountLots(f.token));
        return receipted(receipt, { farmerToken: f.token, erased: true, lotsMarkedUnverifiable: Number((lots as unknown as { n: number }[])[0]?.n ?? 0) } satisfies ErasureResult);
      });
    },

    async createDiaryInput(req) {
      const u = user(req);
      const b = parse(diaryBody, req.body, 'diary entry');
      const farmerId = u.role === 'member' ? u.id : b.farmerId;
      if (!farmerId) throw invalid('farmerId is required when a VLE records an entry.');
      const f = await getFarmer(farmerId);
      if (f.erased) throw new HttpError('ERR_INVALID_STATE', 'This member has erased their data.');
      const ps = await ctx.db.select().from(plots).where(eq(plots.farmerId, f.id));
      const plot = b.plotId ? ps.find((p) => p.plotId === b.plotId) : ps.find((p) => p.crops.includes(b.crop)) ?? ps[0];
      if (!plot) throw invalid('This member has no plot for that crop.');
      const id = randomUUID(), phiClearOn = addDays(b.appliedOn, b.phiDays);
      const hash = hashCanonical({ id, farmerToken: f.token, plotId: plot.plotId, crop: b.crop, product: b.product, activeIngredient: b.activeIngredient, dose: b.dose, appliedOn: b.appliedOn, phiDays: b.phiDays });
      return ctx.db.transaction(async (tx) => {
        const { receipt } = await submit(ctx, fabricUserOf(u), 'trace-channel', 'lot-lifecycle', 'RecordInputEvent', [f.token, hash, b.crop, b.appliedOn, phiClearOn], ENDORSE.trace);
        await tx.insert(diaryInputs).values({ id, farmerId: f.id, plotId: plot.plotId, crop: b.crop, product: b.product, activeIngredient: b.activeIngredient, dose: b.dose, appliedOn: b.appliedOn, phiDays: b.phiDays, phiClearOn, hash, txId: receipt.txId, blockNumber: receipt.blockNumber });
        const resource: DiaryInput = { id, farmerId: f.id, product: b.product, activeIngredient: b.activeIngredient, dose: b.dose, appliedOn: b.appliedOn, phiDays: b.phiDays, crop: b.crop, plotId: plot.plotId, hash, phiClearOn, proof: { txId: receipt.txId, blockNumber: receipt.blockNumber, channel: receipt.channel } };
        return receipted(receipt, resource);
      });
    },

    async listDiaryInputs(req) {
      const u = user(req);
      const q = req.query as { farmerId?: string; cursor?: string; limit?: string };
      const farmerId = u.role === 'member' ? u.id : q.farmerId;
      if (!farmerId) throw invalid('farmerId is required.');
      if (u.role === 'member' && q.farmerId && q.farmerId !== u.id) throw forbidden('A member can read only their own diary.');
      const { limit, offset } = pageParams(q);
      const rows = await ctx.db.select().from(diaryInputs).where(eq(diaryInputs.farmerId, farmerId)).orderBy(asc(diaryInputs.appliedOn), asc(diaryInputs.id)).limit(limit + 1).offset(offset);
      const items: DiaryInput[] = rows.slice(0, limit).map((r) => ({
        id: r.id, farmerId: r.farmerId, product: r.product, activeIngredient: r.activeIngredient, dose: r.dose, appliedOn: r.appliedOn, phiDays: r.phiDays, crop: r.crop as Commodity,
        ...(r.plotId ? { plotId: r.plotId } : {}), hash: r.hash, phiClearOn: r.phiClearOn, ...(r.txId ? { proof: { txId: r.txId, blockNumber: r.blockNumber ?? 0, channel: 'trace-channel' as const } } : {}),
      }));
      return { items, nextCursor: nextCursor(offset, limit, rows.length) };
    },
  };
}

const ctxSqlCountLots = (token: string) => sql`select count(*)::int as n from lots_view where farmer_token = ${token}`;
